new='''  app.post("/orders/:id/refund", async (req, res) => {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id < 1) return sendError(res, 404, "not_found", "Order not found");
    const user = res.locals.user;

    // Lock the order row for the whole refund so concurrent requests can't both refund it. The
    // idempotency key additionally makes a retry after a failed commit safe at the provider.
    const client = await pool.connect();
    try {
      await client.query("begin");
      const { rows } = await client.query(
        "select id, user_id, status, total_cents, payment_id from orders where id = $1 for update",
        [id],
      );
      const order = rows[0];
      if (!order || (order.user_id !== user.id && user.role !== "admin")) {
        await client.query("rollback");
        return sendError(res, 404, "not_found", "Order not found");
      }
      if (order.status !== "paid" || !order.payment_id) {
        await client.query("rollback");
        return sendError(res, 409, "not_refundable", `Only paid orders can be refunded (status: ${order.status})`);
      }
      await payments.refund({
        paymentId: order.payment_id,
        amountCents: order.total_cents,
        idempotencyKey: `refund-order-${order.id}`,
      });
      await client.query("update orders set status = 'refunded' where id = $1", [id]);
      await client.query("commit");
      res.json({ id: order.id, status: "refunded", refunded_cents: order.total_cents });
    } catch (err) {
      await client.query("rollback").catch(() => {});
      throw err;
    } finally {
      client.release();
    }
  });

  app.use((err: Error'''
